SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state", "n_short", "n_price", "n_due", 'hold_ar' AS "route", 'overdue invoices' AS "verdict_reason"
FROM (SELECT "t24"."order_number", "t24"."customer", "t24"."channel", "t24"."fulfilling_warehouse", "t24"."value", "t24"."placed_date", "t24"."state", COALESCE("t24"."n_short", 0) AS "n_short", COALESCE("t24"."n_price", 0) AS "n_price", COALESCE("t30"."n_due", 0) AS "n_due"
        FROM (SELECT "t12"."order_number", "t12"."customer", "t12"."channel", "t12"."fulfilling_warehouse", "t12"."value", "t12"."placed_date", "t12"."state", "t12"."n_short", "t23"."n_price"
                FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "t11"."n_short"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                FROM (SELECT "t6"."order_number", "t6"."customer", "t6"."channel", "t6"."fulfilling_warehouse", "t6"."value", "t6"."placed_date", "t6"."state", "t6"."line_no", "t6"."item", "t6"."quantity", "t6"."unit_price", "t6"."ext_sales_price", "t6"."warehouse", "t6"."sold_date", "t6"."customer0", "t6"."channel0", "t6"."as_of_date", "t6"."quantity_on_hand", "t7"."warehouse" AS "warehouse0", "t7"."from_date", "t7"."to_date", "t7"."reason", COALESCE("t6"."quantity_on_hand", 0) AS "on_hand", "t7"."warehouse" IS NOT NULL AS "outage"
                                        FROM (SELECT "t3"."order_number", "t3"."customer", "t3"."channel", "t3"."fulfilling_warehouse", "t3"."value", "t3"."placed_date", "t3"."state", "t3"."line_no", "t3"."item", "t3"."quantity", "t3"."unit_price", "t3"."ext_sales_price", "t3"."warehouse", "t3"."sold_date", "t3"."customer0", "t3"."channel0", "t5"."as_of_date", "t5"."quantity_on_hand"
                                                FROM (SELECT "t2"."order_number", "t2"."customer", "t2"."channel", "t2"."fulfilling_warehouse", "t2"."value", "t2"."placed_date", "t2"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t2"
                                                            INNER JOIN "sales_line" ON "t2"."order_number" = "sales_line"."order_number") AS "t3"
                                                    LEFT JOIN (SELECT "inventory"."as_of_date", "inventory"."item", "inventory"."warehouse", "inventory"."quantity_on_hand"
                                                        FROM "inventory"
                                                            INNER JOIN (SELECT "item", "warehouse", MAX("as_of_date") AS "_ttrp_latest_n8"
                                                                FROM "inventory"
                                                                GROUP BY "item", "warehouse") AS "t4" ON "inventory"."item" = "t4"."item" AND "inventory"."warehouse" = "t4"."warehouse" AND "inventory"."as_of_date" = "t4"."_ttrp_latest_n8") AS "t5" ON "t3"."item" = "t5"."item" AND "t3"."warehouse" = "t5"."warehouse") AS "t6"
                                            LEFT JOIN (SELECT *
                                                FROM "warehouse_outage"
                                                WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t7" ON "t6"."warehouse" = "t7"."warehouse") AS "t8"
                                WHERE "t8"."outage" OR "t8"."on_hand" < "t8"."quantity"
                                GROUP BY "order_number") AS "t11" ON "t0"."order_number" = "t11"."order_number") AS "t12"
                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_price"
                        FROM (SELECT "t15"."order_number", "t15"."line_no", "t15"."item", "t15"."unit_price", "t15"."customer", "t15"."channel", "t15"."placed_date", "t19"."price"
                                FROM (SELECT "t14"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t14"."customer", "t14"."channel", "t14"."placed_date"
                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                FROM "order"
                                                WHERE "state" IN ('held', 'placed')) AS "t14"
                                            INNER JOIN "sales_line" AS "sales_line0" ON "t14"."order_number" = "sales_line0"."order_number") AS "t15"
                                    INNER JOIN (SELECT "t18"."order_number", "t18"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                        FROM (SELECT "t17"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t17"."customer", "t17"."channel", "t17"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t17"
                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t17"."order_number" = "sales_line1"."order_number") AS "t18"
                                            LEFT JOIN "customer_price" ON "t18"."item" = "customer_price"."item" AND "t18"."customer" = "customer_price"."customer" AND "t18"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t18"."placed_date" <= "customer_price"."valid_to")
                                            LEFT JOIN "price_list" ON "t18"."item" = "price_list"."item" AND "t18"."channel" = "price_list"."channel" AND "t18"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t18"."placed_date" <= "price_list"."valid_to")) AS "t19" ON "t15"."order_number" = "t19"."order_number" AND "t15"."line_no" = "t19"."line_no") AS "t20"
                        WHERE "t20"."price" IS NULL OR ABS("t20"."unit_price" - "t20"."price") > :tolerance
                        GROUP BY "order_number") AS "t23" ON "t12"."order_number" = "t23"."order_number") AS "t24"
            LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                FROM (SELECT "t26"."order_number", "t26"."customer", "t26"."channel", "t26"."fulfilling_warehouse", "t26"."value", "t26"."placed_date", "t26"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t26"
                            INNER JOIN "invoice" ON "t26"."customer" = "invoice"."customer") AS "t27"
                WHERE "t27"."status" = 'open' AND "t27"."due" < :as_of
                GROUP BY "order_number") AS "t30" ON "t24"."order_number" = "t30"."order_number") AS "t31"
WHERE "t31"."n_due" > 0
